"""Role-filtered training content; administrator chapters never reach public clients."""
from __future__ import annotations
import json
from pathlib import Path


def chapter(key, title, summary, text, *, admin=False):
    lessons = []
    for line in text.strip().splitlines():
        label, action, result = line.split('|', 2)
        lessons.append({'button': label.strip(), 'action': action.strip(), 'result': result.strip()})
    return {'id':key,'title':title,'summary':summary,'lessons':lessons,'admin':admin}


